// Story spec: narrative + annotated charts + caveats (plain JS)
const story = {
  title: "Shoes drove Q3 growth; hats need attention",
  context: "4 categories, $637 tracked revenue, Sep-Oct window",
  tension: "hats convert views at 5.6% vs shoes 25% (funnel Ch.8)",
  resolution: "Fix hats PDP media first (expected +$X); shoes inventory second",
  caveats: ["n=14 developers sample", "Oct-12 week missing (flagged)"],
};
// Title argues, tension quantifies, resolution acts, caveats bound — complete.

