function titleScore(title, chart) {
  const argues = /drove|beats|grew|fell|leads|lags/i.test(title);
  const cited = chart.numbers >= 2 && chart.caveats >= 1;
  return { argues, cited, strong: argues && cited };
}
const good = { numbers: 3, caveats: 1 };
const vague = { numbers: 0, caveats: 0 };
console.log(JSON.stringify({ t: 'Shoes drove Q3 growth', ...titleScore('Shoes drove Q3 growth', good) }));
console.log(JSON.stringify({ t: 'Sales by month', ...titleScore('Sales by month', vague) }));
console.log('rule: argue + cite, or describe nothing');

